#include <stdio.h>

int main(void) {
    int a[3] = {7, 2, 5};
    int s = 0;
    int i;

    for (i = 0; i < 3; i++) {
        s = s + a[i];
    }

    printf("sum = %d\n", s);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node *next;
} Node;

/* 头插法：成功返回 1，失败返回 0；失败时链表保持原状 */
int push_front(Node **head, int value) {
    Node *n = (Node *)malloc(sizeof(Node));
    if (n == NULL) {
        return 0;              /* 分配失败：不改动 *head 和旧结点 */
    }
    n->data = value;
    n->next = *head;           /* 新结点指向当前首结点（空链表时为 NULL） */
    *head = n;                 /* head 改为指向新结点 */
    return 1;
}

void print_list(const Node *head) {
    const Node *p = head;
    while (p != NULL) {
        printf("%d ", p->data);
        p = p->next;
    }
    printf("\n");
}

void free_list(Node **head) {
    Node *p = *head;
    while (p != NULL) {
        Node *next = p->next;  /* 先保存后继 */
        free(p);               /* 再释放当前结点 */
        p = next;
    }
    *head = NULL;              /* 防止悬空指针 */
}

int main(void) {
    Node *head = NULL;         /* 空链表：head -> NULL */

    printf("%d\n", push_front(&head, 3));
    printf("%d\n", push_front(&head, 8));

    print_list(head);

    free_list(&head);
    printf("head == NULL: %d\n", head == NULL);
    return 0;
}
